    81  /**
    82   * Returns whether or not an H3 index is a valid cell (hexagon or pentagon).
    83   * @param h The H3 index to validate.
    84   * @return 1 if the H3 index if valid, and 0 if it is not.
    85   */
    86  int H3_EXPORT(isValidCell)(H3Index h) {
    87      if (H3_GET_HIGH_BIT(h) != 0) return 0;
    88
    89      if (H3_GET_MODE(h) != H3_HEXAGON_MODE) return 0;
    90
    91      if (H3_GET_RESERVED_BITS(h) != 0) return 0;
    92
    93      int baseCell = H3_GET_BASE_CELL(h);
    94      if (baseCell < 0 || baseCell >= NUM_BASE_CELLS) {  // LCOV_EXCL_BR_LINE
    95          // Base cells less than zero can not be represented in an index
    96          return 0;
    97      }
    98
    99      int res = H3_GET_RESOLUTION(h);
   100      if (res < 0 || res > MAX_H3_RES) {  // LCOV_EXCL_BR_LINE
   101          // Resolutions less than zero can not be represented in an index
   102          return 0;
   103      }
   104
   105      bool foundFirstNonZeroDigit = false;
   106      for (int r = 1; r <= res; r++) {
   107          Direction digit = H3_GET_INDEX_DIGIT(h, r);
   108
   109          if (!foundFirstNonZeroDigit && digit != CENTER_DIGIT) {
   110              foundFirstNonZeroDigit = true;
   111              if (_isBaseCellPentagon(baseCell) && digit == K_AXES_DIGIT) {
   112                  return 0;
   113              }
   114          }
   115
   116          if (digit < CENTER_DIGIT || digit >= NUM_DIGITS) return 0;
   117      }
   118
   119      for (int r = res + 1; r <= MAX_H3_RES; r++) {
   120          Direction digit = H3_GET_INDEX_DIGIT(h, r);
   121          if (digit != INVALID_DIGIT) return 0;
   122      }
   123
   124      return 1;
   125  }
