   127  /**
   128   * Initializes an H3 index.
   129   * @param hp The H3 index to initialize.
   130   * @param res The H3 resolution to initialize the index to.
   131   * @param baseCell The H3 base cell to initialize the index to.
   132   * @param initDigit The H3 digit (0-7) to initialize all of the index digits to.
   133   */
   134  void setH3Index(H3Index *hp, int res, int baseCell, Direction initDigit) {
   135      H3Index h = H3_INIT;
   136      H3_SET_MODE(h, H3_HEXAGON_MODE);
   137      H3_SET_RESOLUTION(h, res);
   138      H3_SET_BASE_CELL(h, baseCell);
   139      for (int r = 1; r <= res; r++) H3_SET_INDEX_DIGIT(h, r, initDigit);
   140      *hp = h;
   141  }
