   143  /**
   144   * cellToParent produces the parent index for a given H3 index
   145   *
   146   * @param h H3Index to find parent of
   147   * @param parentRes The resolution to switch to (parent, grandparent, etc)
   148   *
   149   * @return H3Index of the parent, or H3_NULL if you actually asked for a child
   150   */
   151  H3Index H3_EXPORT(cellToParent)(H3Index h, int parentRes) {
   152      int childRes = H3_GET_RESOLUTION(h);
   153      if (parentRes < 0 || parentRes > MAX_H3_RES) {
   154          return H3_NULL;
   155      } else if (parentRes > childRes) {
   156          return H3_NULL;
   157      } else if (parentRes == childRes) {
   158          return h;
   159      }
   160      H3Index parentH = H3_SET_RESOLUTION(h, parentRes);
   161      for (int i = parentRes + 1; i <= childRes; i++) {
   162          H3_SET_INDEX_DIGIT(parentH, i, H3_DIGIT_MASK);
   163      }
   164      return parentH;
   165  }
