   241  /**
   242   * Zero out index digits from start to end, inclusive.
   243   * No-op if start > end.
   244   */
   245  H3Index _zeroIndexDigits(H3Index h, int start, int end) {
   246      if (start > end) return h;
   247
   248      H3Index m = 0;
   249
   250      m = ~m;
   251      m <<= H3_PER_DIGIT_OFFSET * (end - start + 1);
   252      m = ~m;
   253      m <<= H3_PER_DIGIT_OFFSET * (MAX_H3_RES - end);
   254      m = ~m;
   255
   256      return h & m;
   257  }
