   259  /**
   260   * cellToCenterChild produces the center child index for a given H3 index at
   261   * the specified resolution
   262   *
   263   * @param h H3Index to find center child of
   264   * @param childRes The resolution to switch to
   265   *
   266   * @return H3Index of the center child, or H3_NULL if you actually asked for a
   267   * parent
   268   */
   269  H3Index H3_EXPORT(cellToCenterChild)(H3Index h, int childRes) {
   270      if (!_hasChildAtRes(h, childRes)) return H3_NULL;
   271
   272      h = _zeroIndexDigits(h, H3_GET_RESOLUTION(h) + 1, childRes);
   273      H3_SET_RESOLUTION(h, childRes);
   274
   275      return h;
